import math
import pathlib
import statistics
import subprocess
import sys
import tempfile
import zipfile

ALIGN_SUFFIX = ".faa.mafft.clipkit"
TREE_SUFFIX = ".faa.mafft.clipkit.treefile"

def extract_archive(archive_path, out_dir):
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            if member.is_dir():
                continue
            name = pathlib.PurePosixPath(member.filename)
            if len(name.parts) != 1:
                continue
            archive.extract(member, out_dir)

def paired_files(out_dir):
    files = {p.name: p for p in pathlib.Path(out_dir).iterdir() if p.is_file()}
    alignments = {
        name[:-len(ALIGN_SUFFIX)]: path
        for name, path in files.items()
        if name.endswith(ALIGN_SUFFIX)
    }
    trees = {
        name[:-len(TREE_SUFFIX)]: path
        for name, path in files.items()
        if name.endswith(TREE_SUFFIX)
    }
    return [(key, alignments[key], trees[key]) for key in sorted(set(alignments) & set(trees))]

def run_phykit(alignment, tree):
    result = subprocess.run(
        [
            "phykit",
            "treeness_over_rcv",
            "--alignment",
            str(alignment),
            "--tree",
            str(tree),
        ],
        check=True,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    for line in reversed(result.stdout.splitlines()):
        values = line.strip().split()
        if len(values) >= 3:
            try:
                parsed = tuple(float(value) for value in values[:3])
            except ValueError:
                continue
            if all(math.isfinite(value) for value in parsed):
                return parsed
    raise RuntimeError("PhyKit returned no three-column treeness/RCV result")

def main():
    animals_zip, fungi_zip = sys.argv[1:3]
    with tempfile.TemporaryDirectory() as temp_dir:
        temp_path = pathlib.Path(temp_dir)
        groups = [
            ("animals", pathlib.Path(temp_dir) / "animals"),
            ("fungi", pathlib.Path(temp_dir) / "fungi"),
        ]
        pathlib.Path(groups[0][1]).mkdir()
        pathlib.Path(groups[1][1]).mkdir()
        extract_archive(animals_zip, groups[0][1])
        extract_archive(fungi_zip, groups[1][1])

        rows = []
        medians = {}
        for group, directory in groups:
            pairs = paired_files(directory)
            expected = {"animals": 100, "fungi": 249}[group]
            if len(pairs) != expected:
                raise RuntimeError("Unexpected paired-file count for %s: %d (expected %d)" % (group, len(pairs), expected))
            treeness_values = []
            for ortholog, alignment, tree in pairs:
                tor, treeness, rcv = run_phykit(alignment, tree)
                rows.append((group, ortholog, tor, treeness, rcv))
                treeness_values.append(treeness)
            medians[group] = statistics.median(treeness_values)

        with open("metrics.tsv", "w", encoding="utf-8") as output:
            output.write("group\tortholog\ttreeness_over_rcv\ttreeness\trcv\n")
            for group, ortholog, tor, treeness, rcv in rows:
                output.write("%s\t%s\t%.12g\t%.12g\t%.12g\n" % (group, ortholog, tor, treeness, rcv))

        difference = medians["fungi"] - medians["animals"]
        with open("summary.tsv", "w", encoding="utf-8") as output:
            output.write("group\tn\tmedian_treeness\n")
            output.write("animals\t%d\t%.12g\n" % (100, medians["animals"]))
            output.write("fungi\t%d\t%.12g\n" % (249, medians["fungi"]))
            output.write("difference_fungi_minus_animals\t%d\t%.12g\n" % (349, difference))

if __name__ == "__main__":
    main()
PY
